const raw = msg.payload;
const down = (raw === 'unavailable' || raw === 'unknown' || raw == null || raw === '');

if (!msg._test) {
    const prev = flow.get('monarch_integration_down') === true;
    if (down === prev) return null;
    flow.set('monarch_integration_down', down);
}

const tag = msg._test ? '🧪 TEST: ' : '';
if (down) {
    msg.payload = {
        title: tag + '⚠️ Monarch Integration Down',
        message: 'Monarch sensors are unavailable — portfolio holdings and the P&L sensor will read $0 until it reconnects. Reload MonarchMoney (Settings → Devices & Services → Reload) or re-authenticate.',
        color: '#D32F2F',
        channel: 'Flow Errors'
    };
} else {
    msg.payload = {
        title: tag + '✅ Monarch Integration Restored',
        message: 'Monarch sensors are reporting again. Holdings and the P&L sensor are back.',
        color: '#2E7D32',
        channel: 'Flow Errors'
    };
}
return msg;
